import{_ as t,o as r,c as s,a2 as d}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"53 - Event Bus","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/53-event-bus.md","filePath":"developers/design-documentation/53-event-bus.md"}'),o={name:"developers/design-documentation/53-event-bus.md"};function a(i,e,n,c,l,p){return r(),s("div",null,[...e[0]||(e[0]=[d(`<h1 id="_53-event-bus" tabindex="-1">53 - Event Bus <a class="header-anchor" href="#_53-event-bus" aria-label="Permalink to &quot;53 - Event Bus&quot;">​</a></h1><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p><code>utils/event_bus.py</code> is a lightweight, <strong>per-process</strong> topic bus for asynchronous order side effects. It is not the cross-process market-data bus; ZeroMQ owns that job.</p><p>Each Flask worker that imports the global singleton has its own subscriber registry and 10-worker <code>ThreadPoolExecutor</code>. A service publishes in the process handling the request, and that process dispatches its local subscribers.</p><p>Dispatch is bounded. <code>EventBus.DEFAULT_MAX_PENDING</code> is 1000 callbacks queued-or-running; beyond that, further callbacks are dropped rather than queued, because the executor&#39;s own work queue is unbounded and a publisher that outruns its subscribers would otherwise grow it until the process is killed. Drops are counted and logged sparsely, and <code>bus.stats()</code> reports pending/max/dropped for health reporting.</p><h2 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>order/sandbox service</span></span>
<span class="line"><span>  -&gt; typed event with topic</span></span>
<span class="line"><span>  -&gt; EventBus.publish()</span></span>
<span class="line"><span>  -&gt; shared per-process thread pool</span></span>
<span class="line"><span>     -&gt; log subscriber</span></span>
<span class="line"><span>     -&gt; Socket.IO subscriber</span></span>
<span class="line"><span>     -&gt; Telegram subscriber</span></span>
<span class="line"><span>     -&gt; WhatsApp subscriber</span></span>
<span class="line"><span>     -&gt; ZeroMQ proxy-relay subscriber</span></span>
<span class="line"><span>     -&gt; strategy book subscriber</span></span></code></pre></div><p>Callbacks are copied under a lock and submitted without blocking the publisher. <code>_safe_call</code> catches/logs subscriber exceptions so notification or logging failure cannot change the order response.</p><h2 id="topics" tabindex="-1">Topics <a class="header-anchor" href="#topics" aria-label="Permalink to &quot;Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Event</th></tr></thead><tbody><tr><td><code>order.placed</code></td><td>Successful single order</td></tr><tr><td><code>order.failed</code></td><td>Failed order</td></tr><tr><td><code>order.no_action</code></td><td>Smart order already at target</td></tr><tr><td><code>order.modified</code>, <code>order.modify_failed</code></td><td>Modify result</td></tr><tr><td><code>order.cancelled</code>, <code>order.cancel_failed</code></td><td>Cancel result</td></tr><tr><td><code>orders.all_cancelled</code></td><td>Cancel-all summary</td></tr><tr><td><code>order.update</code></td><td>Async broker postback / order-WS fill or rejection, and sandbox engine transitions</td></tr><tr><td><code>gtt.placed</code>, <code>gtt.failed</code></td><td>GTT placement result</td></tr><tr><td><code>gtt.modified</code>, <code>gtt.modify_failed</code></td><td>GTT modify result</td></tr><tr><td><code>gtt.cancelled</code>, <code>gtt.cancel_failed</code></td><td>GTT cancel result</td></tr><tr><td><code>gtt.triggered</code>, <code>gtt.expired</code></td><td>GTT lifecycle transitions</td></tr><tr><td><code>position.closed</code></td><td>Close-position summary</td></tr><tr><td><code>basket.completed</code></td><td>Basket summary</td></tr><tr><td><code>split.completed</code></td><td>Split summary</td></tr><tr><td><code>options.completed</code></td><td>Options-order summary</td></tr><tr><td><code>multiorder.completed</code></td><td>Multi-leg summary</td></tr><tr><td><code>analyzer.error</code></td><td>Analyzer validation/runtime error</td></tr><tr><td><code>sandbox.order_filled</code></td><td>Engine-driven fill refresh</td></tr><tr><td><code>sandbox.auto_squareoff</code></td><td>Engine-driven square-off refresh</td></tr><tr><td><code>sandbox.t1_settlement</code></td><td>Engine-driven settlement refresh</td></tr></tbody></table><p>Batch services suppress child events and publish one summary, preventing duplicate logs/chat alerts.</p><h2 id="subscribers" tabindex="-1">Subscribers <a class="header-anchor" href="#subscribers" aria-label="Permalink to &quot;Subscribers&quot;">​</a></h2><p><code>subscribers/register_all()</code> wires log, Socket.IO, Telegram, and WhatsApp callbacks for the order and GTT topics. Sandbox engine-internal topics go only to Socket.IO because they are UI refresh signals rather than user API calls; they are not duplicated into analyzer logs or chat alerts. <code>order.update</code> is engine-driven and broker-driven for the same reason: it goes to Socket.IO and to <code>wsproxy_subscriber</code>, which republishes it on the ZeroMQ bus so the WebSocket proxy can relay it to clients that sent <code>subscribe_orders</code>.</p><p><code>subscribers/strategy_book_subscriber.register(bus)</code> is wired separately, from the database-initialization thread in <code>app.py</code> rather than from <code>register_all()</code>, because it must be listening before the first order is accepted. It subscribes to <code>order.placed</code>, <code>order.update</code>, and the four batch-completion topics.</p><p>Telegram/WhatsApp subscribers skip failure and analyzer-error chat notifications. The log and Socket.IO consumers still record/emit the applicable state.</p><h2 id="event-data" tabindex="-1">Event Data <a class="header-anchor" href="#event-data" aria-label="Permalink to &quot;Event Data&quot;">​</a></h2><p>Order events carry mode, API type, strategy, request/response data, and fields needed for notification formatting. API keys may be passed in memory for username resolution but must be stripped from persisted request logs. Do not add broker tokens or other decrypted credentials to an event.</p><h2 id="why-per-process" tabindex="-1">Why Per-Process <a class="header-anchor" href="#why-per-process" aria-label="Permalink to &quot;Why Per-Process&quot;">​</a></h2><p>The bus decouples side effects on a single request path with minimal dependencies. It makes no durability or cross-worker delivery guarantee. Features that require cross-process delivery, replay, or durable queues need a different transport; do not infer those properties from this bus.</p><h2 id="adding-an-event-or-subscriber" tabindex="-1">Adding An Event Or Subscriber <a class="header-anchor" href="#adding-an-event-or-subscriber" aria-label="Permalink to &quot;Adding An Event Or Subscriber&quot;">​</a></h2><ol><li>Add a typed event under <code>events/</code> with a stable topic.</li><li>Publish once at the service boundary, after the outcome is known.</li><li>Add callbacks and registrations in <code>subscribers/__init__.py</code>.</li><li>Keep callbacks idempotent where duplicate upstream requests are possible.</li><li>Test publisher response independence and subscriber failure isolation.</li></ol><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>utils/event_bus.py</code></td><td>Bus and executor singleton</td></tr><tr><td><code>events/</code></td><td>Typed payloads</td></tr><tr><td><code>subscribers/__init__.py</code></td><td>Registration</td></tr><tr><td><code>subscribers/log_subscriber.py</code></td><td>Database logging</td></tr><tr><td><code>subscribers/socketio_subscriber.py</code></td><td>Browser refresh/events</td></tr><tr><td><code>subscribers/telegram_subscriber.py</code></td><td>Telegram alerts</td></tr><tr><td><code>subscribers/whatsapp_subscriber.py</code></td><td>WhatsApp alerts</td></tr><tr><td><code>subscribers/wsproxy_subscriber.py</code></td><td>ZeroMQ relay of order updates to the proxy</td></tr><tr><td><code>subscribers/strategy_book_subscriber.py</code></td><td>Per-strategy position book</td></tr></tbody></table>`,23)])])}const h=t(o,[["render",a]]);export{b as __pageData,h as default};
